const uint8_t font16_count = 25;

/* 按 UTF-8 前 3 字节查找汉字点阵 */
const uint8_t *font16_find(const char *hz)
{
    for (uint8_t i = 0; i < font16_count; i++) {
        if (font16_tab[i].name[0] == hz[0] &&
            font16_tab[i].name[1] == hz[1] &&
            font16_tab[i].name[2] == hz[2]) {
            return font16_tab[i].data;
        }
    }
    return 0;
}
